name: AI Docs Review Command

on:
  workflow_dispatch:
    inputs:
      pr_number:
        description: 'Pull Request Number'
        required: true
        type: number
      comment_id:
        description: 'Comment ID (for reaction updates)'
        required: false
        type: string

permissions:
  contents: read
  pull-requests: write
  issues: write

jobs:
  ai-docs-review:
    runs-on: ubuntu-latest
    steps:
      - name: Validate Inputs
        id: validate
        run: |
          if [ -z "${{ github.event.inputs.pr_number }}" ]; then
            echo "::error::PR number is required"
            exit 1
          fi
          echo "pr_number=${{ github.event.inputs.pr_number }}" >> $GITHUB_OUTPUT

      - name: Authenticate as Octavia Bot
        id: auth
        uses: actions/create-github-app-token@v1
        with:
          app-id: ${{ secrets.OCTAVIA_BOT_APP_ID }}
          private-key: ${{ secrets.OCTAVIA_BOT_PRIVATE_KEY }}

      - name: Post Started Comment
        uses: actions/github-script@v7
        with:
          github-token: ${{ steps.auth.outputs.token }}
          script: |
            const prNumber = ${{ github.event.inputs.pr_number }};
            const commentBody = `🤖 **AI Docs Review Started**

            Analyzing connector changes for documentation recommendations...`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: commentBody
            });

      - name: Fetch Changed Files
        id: fetch-files
        uses: actions/github-script@v7
        with:
          github-token: ${{ steps.auth.outputs.token }}
          script: |
            const prNumber = ${{ github.event.inputs.pr_number }};

            // Fetch files from the PR diff
            const response = await github.rest.pulls.listFiles({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber,
              per_page: 100
            });

            const files = response.data.map(file => file.filename);

            // Save files to a temporary file for processing
            const fs = require('fs');
            fs.writeFileSync('/tmp/changed_files.json', JSON.stringify(files));

            return files;

      - name: Check for Connector Changes
        id: check-connectors
        run: |
          # Read changed files
          files=$(cat /tmp/changed_files.json)

          # Check if any file matches the connector path pattern
          # Pattern: ^airbyte-integrations/connectors/[^/]+/
          has_connectors=false

          # Use jq to iterate through files if available, otherwise use python
          if command -v jq &> /dev/null; then
            has_connectors=$(echo "$files" | jq -r '.[]' | grep -E '^airbyte-integrations/connectors/[^/]+/' | head -n 1)
          else
            has_connectors=$(echo "$files" | python3 -c "
import sys, json, re
files = json.load(sys.stdin)
pattern = re.compile(r'^airbyte-integrations/connectors/[^/]+/')
for f in files:
    if pattern.match(f):
        print(f)
        break
")
          fi

          if [ -n "$has_connectors" ]; then
            echo "has_connector_changes=true" >> $GITHUB_OUTPUT
            echo "connector_path=$has_connectors" >> $GITHUB_OUTPUT
          else
            echo "has_connector_changes=false" >> $GITHUB_OUTPUT
          fi

      - name: Post Skip Comment (No Connector Changes)
        if: steps.check-connectors.outputs.has_connector_changes == 'false'
        uses: actions/github-script@v7
        with:
          github-token: ${{ steps.auth.outputs.token }}
          script: |
            const prNumber = ${{ github.event.inputs.pr_number }};
            const commentBody = `⏭️ **AI Docs Review Skipped**

            No connector changes detected in this PR. The `/ai-docs-review` command only analyzes PRs with changes to files matching the pattern:

            \`\`\`
            ^airbyte-integrations/connectors/[^/]+/
            \`\`\`

            If you believe this is an error, please verify the file paths in the PR diff.`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: commentBody
            });

      - name: Trigger Devin AI Action
        if: steps.check-connectors.outputs.has_connector_changes == 'true'
        uses: actions/github-script@v7
        with:
          github-token: ${{ steps.auth.outputs.token }}
          script: |
            const prNumber = ${{ github.event.inputs.pr_number }};
            const connectorPath = '${{ steps.check-connectors.outputs.connector_path }}';

            // Post a comment indicating Devin is being triggered
            const commentBody = `🚀 **Triggering Devin AI**

            Connector changes detected in: \`${connectorPath}\`

            Triggering playbook macro: \`!connectordocs_pr_review\`

            *Please wait for Devin to complete the analysis and post recommendations.*`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: commentBody
            });

            // Trigger the Devin workflow via workflow_dispatch
            // Note: This assumes a separate workflow exists that Devin listens to
            // or this is a placeholder for the actual Devin API call
            try {
              await github.rest.actions.createWorkflowDispatch({
                owner: context.repo.owner,
                repo: context.repo.repo,
                workflow_id: 'devin-ai-action.yml', // Adjust if the workflow name differs
                ref: 'main',
                inputs: {
                  pr_number: prNumber.toString(),
                  playbook_macro: '!connectordocs_pr_review',
                  connector_path: connectorPath
                }
              });
              console.log('Successfully triggered Devin AI workflow');
            } catch (error) {
              console.error('Failed to trigger Devin AI workflow:', error.message);
              // Post error comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: `❌ **Error Triggering Devin AI**

                Failed to trigger the Devin AI workflow. Please check the workflow logs for more details.

                Error: \`${error.message}\``
              });
              throw error;
            }

      - name: Handle Errors
        if: failure()
        uses: actions/github-script@v7
        with:
          github-token: ${{ steps.auth.outputs.token }}
          script: |
            const prNumber = ${{ github.event.inputs.pr_number }};
            const errorBody = `❌ **AI Docs Review Failed**

            An error occurred while processing the `/ai-docs-review` command. Please check the workflow run logs for more details.

            If the issue persists, please contact the maintainers.`;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: errorBody
            });
